        'feat_title_b' => 'pensati per il pianoforte',
        'h_studio_title' => 'Studio piano virtuale',
        'h_studio_desc' => 'Esercitati su intervalli, accordi e note direttamente su una tastiera di pianoforte interattiva. Ascolta esattamente come nasce ogni suono e vedilo sui tasti — l\'ambiente di apprendimento più naturale per un pianista.',
        'h_studio_p1' => 'Tastiera di pianoforte interattiva in ogni esercizio',
