        'cta_title_b' => 'nella community Harmoniva?',
        'cta_subtitle' => 'Inizia gratis oggi, condividi i tuoi progressi e mettiti in contatto con insegnanti e musicisti che ti aiutano a crescere.',
        'cta_compare' => 'Confronta i piani',
